steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issue(identifier: \"ENG-9\") {
        id
        identifier
        title
        team { id name }
        milestone { id name state }
      }
      teams {
        nodes {
          id
          name
          cycles(state: active) {
            nodes {
              id
              name
              state
            }
          }
        }
      }
    }"
  }'
